create or replace function public.protect_student_grades() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ declare v_max integer; v_count integer; begin if auth.uid() is null or public.current_app_role()<>'STUDENT' then return new; end if; if tg_table_name='assessment_attempts' then if tg_op='INSERT' then if new.student_id<>auth.uid() then raise exception 'Attempt owner must be the signed-in student'; end if; select max_attempts into v_max from public.assessments where id=new.assessment_id and status='PUBLISHED' and deleted_at is null for update; if v_max is null then raise exception 'Assessment unavailable'; end if; select count(*) into v_count from public.assessment_attempts where assessment_id=new.assessment_id and student_id=auth.uid(); if v_count>=v_max or new.attempt_number<>v_count+1 then raise exception 'Maximum attempts reached or attempt number invalid'; end if; if new.status<>'IN_PROGRESS' or new.total_score is not null or new.graded_at is not null then raise exception 'Students can only start an ungraded attempt'; end if; return new; end if; if new.total_score is distinct from old.total_score or new.graded_at is distinct from old.graded_at or new.student_id is distinct from old.student_id or new.assessment_id is distinct from old.assessment_id or new.attempt_number is distinct from old.attempt_number then raise exception 'Students cannot change grades or attempt ownership'; end if; end if; if tg_table_name='submission_answers' then if tg_op='INSERT' then if new.score is not null or new.graded_by is not null or new.graded_at is not null or new.feedback<>'' then raise exception 'Students cannot submit grading fields'; end if; return new; end if; if new.score is distinct from old.score or new.feedback is distinct from old.feedback or new.graded_by is distinct from old.graded_by or new.graded_at is distinct from old.graded_at then raise exception 'Students cannot change grades'; end if; end if; if tg_table_name='assignment_submissions' then if tg_op='INSERT' then if new.student_id<>auth.uid() or new.score is not null or new.feedback is not null or new.graded_by is not null or new.graded_at is not null then raise exception 'Students cannot submit grading fields or another student’s work'; end if; return new; end if; if new.student_id is distinct from old.student_id or new.assignment_id is distinct from old.assignment_id or new.score is distinct from old.score or new.feedback is distinct from old.feedback or new.graded_by is distinct from old.graded_by or new.graded_at is distinct from old.graded_at then raise exception 'Students cannot change grades or submission ownership'; end if; end if; return new; end $$;
drop trigger if exists protect_attempt_grade on public.assessment_attempts; create trigger protect_attempt_grade before insert or update on public.assessment_attempts for each row execute function public.protect_student_grades();
drop trigger if exists protect_answer_grade on public.submission_answers; create trigger protect_answer_grade before insert or update on public.submission_answers for each row execute function public.protect_student_grades();
drop trigger if exists protect_assignment_grade on public.assignment_submissions; create trigger protect_assignment_grade before insert or update on public.assignment_submissions for each row execute function public.protect_student_grades();
